import React from 'react';
import './App.css';

function App() {
  return (
    <div className="App">
      <main>
        <video id="userVideo" autoPlay muted></video>
        <div>
          <button id="joinButton">Join Meeting</button>
          <button id="hostButton">Host Meeting</button>
        </div>
      </main>
    </div>
  );
}

export default App;
